import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`fire-calculator`,heroCta:`Get Started`,heroTitle:`Build your FIRE plan in minutes`,heroSubtitle:`Perplexity Computer connects to your portfolio and builds you a personalized FIRE calculator.`,inputUrlCta:`Build my FIRE plan`,inputUrlPlaceholder:`Your goals`,inputUrlPrefill:`Connect my portfolio via Plaid. Then build me a comprehensive FIRE (Financial Independence, Retire Early) calculator as a custom web app deployed to a live URL. The app should: 1) Let me input or adjust my annual income, monthly expenses, current savings, investment balances, expected return rate, inflation rate, safe withdrawal rate (default 4%), and target FIRE number, 2) Calculate my FIRE number, current savings rate, and projected years to financial independence under Lean FIRE, Regular FIRE, and Fat FIRE scenarios, 3) Show an interactive chart projecting net worth growth over time with a clear crossover point where passive income exceeds expenses, 4) Include a sensitivity analysis showing how changes in savings rate, return rate, and withdrawal rate impact my FIRE date, 5) Provide a breakdown of monthly investment targets needed to hit each FIRE milestone, 6) Generate a personalized action plan with specific recommendations to accelerate my FIRE timeline - including expense optimization, income growth strategies, and tax-advantaged account maximization, 7) Include a Coast FIRE calculator showing at what point I can stop contributing and still reach my target by traditional retirement age. Save my inputs so I can return and update my numbers over time.`,heroOverlaySteps:[`Analyzing your financial profile and investment data`,`Modeling Lean, Regular, and Fat FIRE scenarios`,`Building your personalized FIRE calculator app`,`Your FIRE plan with interactive projections - ready to explore`],generatingSteps:[`Visiting {url} to extract income, expenses, savings, and investment data`,`Designing an agent to model multiple FIRE scenarios and withdrawal strategies`,`Building an interactive calculator with net worth projections and sensitivity analysis`,`Setting up a personalized action plan to accelerate financial independence`],featureSectionTitle:`From financial snapshot to FIRE roadmap`,featureCardTitles:[`Connects to your finance stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Notion, QuickBooks - Computer pulls your financial data and delivers projections straight into the tools you already use.`,`FIRE number calculation. Net worth projection charts. Savings rate targets. Sensitivity analysis. Coast FIRE milestone. A personalized action plan to retire early.`],capabilitySectionTitle:`Your financial planner, on autopilot`,capabilitySectionSubtitle:`Share your financial profile, step away, come back to a complete FIRE roadmap.`,capabilityCards:[{title:`FIRE Modeling`,description:`Computer can calculate your FIRE number across Lean, Regular, Fat, and Coast FIRE scenarios - accounting for your exact income, expenses, and savings rate.`},{title:`Projection Charts`,description:`Computer can build interactive net worth projections showing your crossover point - where passive income exceeds expenses and work becomes optional.`},{title:`Sensitivity Analysis`,description:`Computer can model how changes in savings rate, market returns, inflation, and withdrawal rate shift your FIRE date - so you can stress-test every assumption.`},{title:`Connect Your Tools`,description:`Computer can pull data from Google Sheets, QuickBooks, Google Drive, and Notion - build workflows across your entire financial planning stack.`},{title:`Track Progress`,description:`Computer can remember your baseline numbers, past projections, and milestone updates - so every recalculation shows real progress toward financial independence.`},{title:`Monitor Milestones`,description:`Computer can watch your savings rate and portfolio growth - and alert you when you hit Coast FIRE, cross a net worth milestone, or need to adjust course.`}]});export{t as default};
